 let deadline=std::time::Instant::now()+std::time::Duration::from_secs(30);let status=loop{if let Some(s)=child.try_wait()?{break s;}anyhow::ensure!(std::time::Instant::now()<deadline,"Normal refusal original process not terminal");tokio::time::sleep(std::time::Duration::from_millis(10)).await;};let output=std::fs::read_to_string(&log_path)?;anyhow::ensure!(status.code().is_some_and(|c|c!=0)&&output.contains(expected)&&std::fs::read_dir(&workspace)?.next().is_none()&&!parent.join(format!("must-not-init-{case}")).exists(),"Normal refusal missed exactguard case={case} log={}",log_path.display());println!("ACTUAL_NORMAL_HISTORICAL_ORIGINAL_PROCESS_REFUSAL_PASS case={case} original_pid={pid} proc_elf_sha256={sha} workspace_empty=true log={}",log_path.display());Ok(())
