 anyhow::ensure!(identity(&original)?==original_identity&&identity(&File::open(&retained)?)?==original_identity&&hash_file(&original,original.metadata()?.len())?==original_sha&&hash_file(&File::open(&retained)?,original.metadata()?.len())?==original_sha&&rows(&retained)?==original_rows,"Sentinel retained original inode/bytes/rows changed");
 println!("ACTUAL_HISTORICAL_FOREIGN_WRITER_PROBE_HELD10_RELEASED42_RENAMED_MAIN_NEITHER_NO_CREATE_ORIGINAL_INODE_HASH_ROWS_SPECIAL_URI_PASS held={held} released={released} missing={missing} root={}",root.display());Ok(())
